Tool response:
Tool: find_cvs_pharmacy
Description: Find Cvs Pharmacy
Parameters:
    {
      "type": "object",
      "properties": {
        "street_address": {
          "type": "string",
          "description": "Street address of the pharmacy",
          "title": "Street Address"
        },
        "city": {
          "type": "string",
          "description": "City of the pharmacy",
          "title": "City"
        },
        "state": {
          "type": "string",
          "description": "State of the pharmacy",
          "title": "State"
        },
        "has_minuteclinic": {
          "type": "boolean",
          "description": "Whether the pharmacy has MinuteClinic service",
          "title": "Has Minuteclinic"
        },
        "name": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Name of the pharmacy (optional filter)",
          "title": "Name"
        }
      },
      "required": [
        "street_address",
        "city",
        "state",
        "has_minuteclinic"
      ]
    }

Tool response:
Tool: find_nurse_practitioner
Description: Find Nurse Practitioner
Parameters:
    {
      "type": "object",
      "properties": {
        "pharmacy_id": {
          "type": "integer",
          "description": "Internal ID of the pharmacy",
          "title": "Pharmacy Id"
        },
        "provider_type": {
          "type": "string",
          "description": "Type of provider (must be 'Nurse Practitioner')",
          "title": "Provider Type"
        },
        "is_active": {
          "type": "boolean",
          "description": "Whether the provider is currently active",
          "title": "Is Active"
        }
      },
      "required": [
        "pharmacy_id",
        "provider_type",
        "is_active"
      ]
    }

